#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n;
    ll code;
    scanf("%d %lld", &n, &code);
    unordered_map<ll, ll> cnt;
    cnt.reserve(n * 2 + 1);
    for (int i = 0; i < n; i++) {
        ll x;
        scanf("%lld", &x);
        cnt[x]++;
    }
    string t = to_string(code);
    auto get = [&](const string &s) -> ll {
        // Fragments are canonical decimals: a part with a leading zero never matches.
        if (s[0] == '0' || s.size() > 18) return 0;
        auto it = cnt.find(stoll(s));
        return it == cnt.end() ? 0 : it->second;
    };
    ll answer = 0;
    for (size_t cut = 1; cut < t.size(); cut++) {
        string l = t.substr(0, cut), r = t.substr(cut);
        ll lc = get(l), rc = get(r);
        answer += lc * rc;
        if (l == r) answer -= lc;  // a position cannot pair with itself
    }
    printf("%lld\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static HashMap<Long, Long> cnt = new HashMap<>();

    static long get(String s) {
        // Fragments are canonical decimals: a part with a leading zero never matches.
        if (s.charAt(0) == '0' || s.length() > 18) return 0;
        return cnt.getOrDefault(Long.parseLong(s), 0L);
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long code = nextLong();
        for (int i = 0; i < n; i++) cnt.merge(nextLong(), 1L, Long::sum);
        String t = Long.toString(code);
        long answer = 0;
        for (int cut = 1; cut < t.length(); cut++) {
            String l = t.substring(0, cut), r = t.substring(cut);
            long lc = get(l), rc = get(r);
            answer += lc * rc;
            if (l.equals(r)) answer -= lc; // a position cannot pair with itself
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	code := nextInt()
	cnt := make(map[int64]int64, n)
	for i := 0; i < n; i++ {
		cnt[nextInt()]++
	}
	t := strconv.FormatInt(code, 10)
	get := func(s string) int64 {
		// Fragments are canonical decimals: a part with a leading zero never matches.
		if s[0] == '0' || len(s) > 18 {
			return 0
		}
		v, _ := strconv.ParseInt(s, 10, 64)
		return cnt[v]
	}
	var answer int64
	for cut := 1; cut < len(t); cut++ {
		l, r := t[:cut], t[cut:]
		lc, rc := get(l), get(r)
		answer += lc * rc
		if l == r {
			answer -= lc // a position cannot pair with itself
		}
	}
	fmt.Println(answer)
}
